'use client'
import { cn, useSignal, useSignalEffect, useSignals } from '@cascivo/core'
import { formatDate, formatRelativeTime } from '@cascivo/i18n'
import type { TimeHTMLAttributes } from 'react'
import styles from './relative-time.module.css'

export interface RelativeTimeProps extends Omit<TimeHTMLAttributes<HTMLTimeElement>, 'dateTime'> {
  /** The instant to describe relative to now. */
  date: Date | number | string
  /**
   * When true, updates the relative time as it elapses.
   *
   * @defaultValue `true`
   * @see the component manifest
   */
  sync?: boolean
  /** Override "now" (ms since epoch). Mainly for deterministic tests; disables the interval. */
  now?: number
  /** Passed through to Intl.RelativeTimeFormat (e.g. `{ numeric: 'auto' }`). */
  format?: Intl.RelativeTimeFormatOptions
}

const SECOND = 1000
const MINUTE = 60 * SECOND
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR
const WEEK = 7 * DAY
const MONTH = 30 * DAY
const YEAR = 365 * DAY

interface Selected {
  value: number
  unit: Intl.RelativeTimeFormatUnit
  nextUpdateMs: number
}

function selectUnit(deltaMs: number): Selected {
  const abs = Math.abs(deltaMs)
  if (abs < MINUTE)
    return { value: Math.round(deltaMs / SECOND), unit: 'second', nextUpdateMs: SECOND }
  if (abs < HOUR)
    return { value: Math.round(deltaMs / MINUTE), unit: 'minute', nextUpdateMs: MINUTE }
  if (abs < DAY) return { value: Math.round(deltaMs / HOUR), unit: 'hour', nextUpdateMs: HOUR }
  if (abs < WEEK) return { value: Math.round(deltaMs / DAY), unit: 'day', nextUpdateMs: DAY }
  if (abs < MONTH) return { value: Math.round(deltaMs / WEEK), unit: 'week', nextUpdateMs: DAY }
  if (abs < YEAR) return { value: Math.round(deltaMs / MONTH), unit: 'month', nextUpdateMs: DAY }
  return { value: Math.round(deltaMs / YEAR), unit: 'year', nextUpdateMs: DAY }
}

const toTimestamp = (date: Date | number | string): number =>
  date instanceof Date ? date.getTime() : typeof date === 'number' ? date : Date.parse(date)

export function RelativeTime({
  date,
  sync = true,
  now: nowProp,
  format,
  className,
  ...props
}: RelativeTimeProps) {
  useSignals()
  const target = toTimestamp(date)
  const isControlled = nowProp !== undefined
  // Seeding from the wall clock during render is impure, and deliberately so: a relative
  // time has no meaning without "now", and seeding from anything stable would render
  // "just now" for every date on the server. The server's clock and the client's differ,
  // so the first client paint is corrected by the effect below — that correction is the
  // component's whole SSR story, not an oversight. Pass `now` to make it pure (tests do).
  // eslint-disable-next-line react-hooks/purity -- see below: the impurity is the feature.
  const now = useSignal(nowProp ?? Date.now())
  if (isControlled) now.value = nowProp as number

  // Correct the server-rendered text against the client clock once on mount, then
  // (when `sync`) tick on an interval whose cadence scales with the magnitude —
  // reading `now.value` re-subscribes the effect so the cadence adapts as time
  // grows. The one-time write matters when `sync` is off: without it the server's
  // relative string would stay frozen after hydration. SSR/no-DOM safe; skipped
  // when controlled (tests drive `now`).
  useSignalEffect(() => {
    if (isControlled || typeof window === 'undefined') return
    now.value = Date.now()
    if (!sync) return
    const { nextUpdateMs } = selectUnit(target - now.value)
    const id = window.setInterval(() => {
      now.value = Date.now()
    }, nextUpdateMs)
    return () => window.clearInterval(id)
  })

  const { value, unit } = selectUnit(target - now.value)
  const text = formatRelativeTime(value, unit, format)
  const iso = new Date(target).toISOString()
  const absolute = formatDate(target, { dateStyle: 'long', timeStyle: 'short' })

  return (
    <time
      dateTime={iso}
      title={absolute}
      className={cn(styles['relativeTime'], className)}
      // Relative text depends on the render-time clock, so server and client
      // differ by the elapsed time. Suppress the expected text mismatch (React
      // keeps the server text and the effect above corrects it post-hydration)
      // rather than discarding the server markup. Pass a fixed `now` for a fully
      // deterministic render.
      suppressHydrationWarning
      {...props}
    >
      {text}
    </time>
  )
}

@layer cascivo.component {
  .relativeTime {
    display: inline;
    color: inherit;
    font: inherit;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'RelativeTime',
  description: 'Displays a date as a localized phrase relative to now, auto-updating',
  category: 'display',
  // The formatted phrase is server-rendered; JS only re-ticks it as the clock moves.
  clientJs: 'enhancement',
  states: ['default'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'date',
      description: 'The date to render relative to now.',
      type: 'Date | number | string',
      required: true,
    },
    {
      name: 'sync',
      description: 'When true, updates the relative time as it elapses.',
      type: 'boolean',
      required: false,
      default: 'true',
    },
    {
      name: 'now',
      type: 'number',
      required: false,
      description:
        'Override "now" (ms); disables the interval. Pass a serialized server timestamp under SSR for a byte-deterministic render.',
    },
    {
      name: 'format',
      description: 'Intl.RelativeTimeFormat options controlling the output.',
      type: 'Intl.RelativeTimeFormatOptions',
      required: false,
    },
  ],
  tokens: [],
  accessibility: {
    role: 'time',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    { title: 'Basic', code: '<RelativeTime date={post.createdAt} />' },
    {
      title: 'Natural language',
      code: '<RelativeTime date={date} format={{ numeric: "auto" }} />',
    },
    { title: 'Static (no ticking)', code: '<RelativeTime date={date} sync={false} />' },
    {
      title: 'SSR deterministic',
      code: '<RelativeTime date={date} now={serverNow} />',
      description:
        'Relative text is clock-dependent, so it is hydration-safe by default (the server text is kept and corrected on the client). Pass a serialized server timestamp via `now` when you need identical server/client output with no post-hydration correction.',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['time', 'date', 'relative', 'i18n', 'display'],
  intent: {
    whenToUse: [
      'Showing how long ago something happened in human terms ("3 minutes ago")',
      'Timestamps in feeds, comments, and activity logs where recency matters more than precision',
      'Anywhere a self-updating relative time is friendlier than an absolute date',
    ],
    whenNotToUse: [
      'Precise timestamps in tables or audit logs — use formatDate for an exact, sortable value',
      'Dates far in the past/future where "2 years ago" is less useful than the actual date',
    ],
    antiPatterns: [
      {
        bad: '<RelativeTime date={date} /> as the only representation of a legal/audit timestamp',
        good: '<time>{formatDate(date)}</time> for exact records; RelativeTime for casual recency',
        why: 'Relative phrases lose precision; the exact date belongs in records (RelativeTime still exposes it via title/datetime)',
      },
    ],
    related: [
      {
        name: 'Stat',
        relationship: 'pairs-with',
        reason: 'Use alongside Stat to timestamp a metric’s last update',
      },
    ],
    a11yRationale:
      'Renders a native <time> element with a machine-readable datetime and the absolute date in the title, so the precise instant is available even though the visible text is relative',
    flexibility: [
      {
        area: 'format',
        level: 'flexible',
        note: 'Pass Intl.RelativeTimeFormat options (e.g. numeric: "auto") to tune the wording',
      },
      {
        area: 'sync',
        level: 'flexible',
        note: 'Disable ticking for static contexts or long-past dates',
      },
    ],
  },
}
